import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def get_sheet(wb, name="Sheet1"):
    if name in wb.sheetnames:
        return wb[name]
    for n in wb.sheetnames:
        if n.lower() == name.lower():
            return wb[n]
    return wb.create_sheet(name)

vws = get_sheet(vals, "Sheet1")
ws = get_sheet(wb, "Sheet1")

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s != "" else None
    return v

max_row = max(vws.max_row or 0, 82)

out = [[None, None] for _ in range(max_row + 1)]
for r in range(1, max_row + 1):
    out[r][0] = clean(vws.cell(r, 1).value)
    out[r][1] = clean(vws.cell(r, 2).value)

def row_is_blank(r):
    return out[r][0] is None and out[r][1] is None

blocks = []
r = 1
while r <= max_row:
    if not row_is_blank(r):
        start = r
        while r <= max_row and not row_is_blank(r):
            r += 1
        blocks.append((start, r - 1))
    else:
        r += 1

for start, end in blocks:
    a0, b0 = out[start]
    is_header = (
        isinstance(a0, str) and
        isinstance(b0, str) and
        a0.lower() == "number" and
        b0.lower() == "name"
    )

    data_start = start + 1 if is_header else start
    if data_start <= end:
        rows = [tuple(out[r]) for r in range(data_start, end + 1)]
        rows.sort(key=lambda x: str(x[0]).strip() if x[0] is not None else "")
        for i, (a, b) in enumerate(rows):
            out[data_start + i][0] = a
            out[data_start + i][1] = b

for r in range(1, max_row + 1):
    ws.cell(r, 1).value = out[r][0]
    ws.cell(r, 2).value = out[r][1]

wb.save(OUT)

print("blocks:", blocks)
print("row1:", out[1])
print("row2:", out[2])
print("row16:", out[16])
print("row17:", out[17])
